independent_commands.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';import crypto from 'node:crypto';import {artifactDigest,taskContractDigest} from './scripts/remediation/board.mjs';
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));const base='docs/remediation/evidence/W06.05/';const a=read(base+'frozen-artifact-v1.json'),b=read(base+'baseline-v1.json'),w=read(base+'worker-checks.json'),c=read('docs/remediation/design/W06.05/task-contract-v1.json');
const pins=a.files.map(f=>({...f,actual:hash(fs.readFileSync(f.path)),match:hash(fs.readFileSync(f.path))===f.sha256}));const originals=w.before_sources.files.map(f=>({path:f.path,sha256:hash(f.content),retained:f.sha256,baseline:b.files.find(x=>x.path===f.path)?.sha256,capture:JSON.parse(w.checks.find(x=>x.id==='original:'+f.path).output).sha256,content_matches_capture:JSON.parse(w.checks.find(x=>x.id==='original:'+f.path).output).content===f.content}));const result={at:new Date().toISOString(),frozen_record_sha256:hash(fs.readFileSync(base+'frozen-artifact-v1.json')),artifact_expected:a.digest,artifact_actual:artifactDigest(a),contract_expected:a.contract_digest,contract_actual:taskContractDigest(c),pins,originals};console.log(JSON.stringify(result,null,2));if(pins.some(p=>!p.match)||artifactDigest(a)!==a.digest||taskContractDigest(c)!==a.contract_digest||originals.some(x=>x.sha256!==x.retained||x.sha256!==x.baseline||x.sha256!==x.capture||!x.content_matches_capture))process.exit(1);
NODE

node --input-type=module <<'NODE'
import fs from 'node:fs';import crypto from 'node:crypto';import {build} from 'esbuild';const hash=b=>crypto.createHash('sha256').update(b).digest('hex');const entryPoints=['src/routes/identity.test.ts','src/learn/holdoutArms.test.ts','src/content/consent.test.ts'];const r=await build({entryPoints,bundle:true,packages:'external',write:false,metafile:true,platform:'node',format:'esm',outdir:'/tmp/w0605-review-no-write',logLevel:'silent'});const inputs=Object.entries(r.metafile.inputs).map(([path,v])=>({path,sha256:hash(fs.readFileSync(path)),bytes:fs.statSync(path).size,imports:v.imports})).sort((a,b)=>a.path.localeCompare(b.path));console.log(JSON.stringify({at:new Date().toISOString(),entryPoints,options:{bundle:true,packages:'external',write:false,metafile:true,platform:'node',format:'esm'},input_count:inputs.length,inputs},null,2));
NODE

